			IndexData.siteDown.checker.vip.nonVip = false;

			IndexData.siteDown.checker.power.isPowerAlarm = false;

			IndexData.siteDown.checker.siteType.n3t = true;
			IndexData.siteDown.checker.siteType.uso = true;
