;// ./src/views/Api/searching/getMcClusterSearch.js


function getMcClusterSearch(query) {
    return new Promise((resolve, reject) => {
        spl.MessageProcessor.process({
            serviceId: "/netdrone_maps_v3/netdrone_maps_v3/netdrone_m_get_mc_cluster_list",
            data: {
                cluster: query
            },
            showErrorMessage: false,
            success: (json) => {
                resolve({ res:json.results });
            },
            error: (error) => {
                console.error(error, "error fetch fme marker");
                reject(error);
            }
        });
    });
}

;// ./src/views/Api/searching/getFmeNameSearch.js


function getFmeNameSearch(fmeName, username) {
    return new Promise((resolve, reject) => {
        spl.MessageProcessor.process({
            serviceId: "/netdrone_maps_v3/netdrone_maps_v4/netdrone_maps_v4_search_fme",
            data: {
                fme_name: fmeName,
                username: username
            },
            showErrorMessage: false,
            success: (json) => {
                resolve({ res:json.results });
            },
            error: (error) => {
                console.error(error, "error fetch fme marker");
                reject(error);
            }
        });
    });
}

;// ./src/views/Api/searching/getSiteNameSearch.js


function getSiteNameSearch(query) {
    return new Promise((resolve, reject) => {
        spl.MessageProcessor.process({
            serviceId: "/netdrone_maps_v3/netdrone_maps_v3/netdrone_m_get_site_name",
            data: {
                sitename: query,
            },
            showErrorMessage: false,
            success: (json) => {
                resolve({ res:json.results });
            },
            error: (error) => {
                console.error(error, "error fetch fme marker");
                reject(error);
            }
        });
    });
}

;// ./src/views/Api/marker/getSelectedMcCluster.js


function getSelectedMcCluster(query) {
	return new Promise((resolve, reject) => {
		spl.MessageProcessor.process({
			serviceId: "/netdrone_maps_v3/netdrone_maps_v4/netdrone_maps_v4_get_all_site_down_markers",
			data: {
				hub_type: ["BIG HUB SITE", "MEDIUM HUB SITE", "SMALL HUB SITE"],
				status: "",
				mc_cluster: query
			},
			showErrorMessage: false,
			success: (json) => {
				resolve({ res: json.results });
			},
			error: (error) => {
				console.error(error, "error fetch fme marker");
				reject(error);
			}
		});
	});
}

