;// ./src/views/Api/countingDwdm/getDwdmSiteInfo.js


function getDwdmSiteInfo(siteid) {
    return new Promise((resolve, reject) => {
        spl.MessageProcessor.process({
            serviceId: "/netdrone_maps_v3/netdrone_maps_v4/netdrone_maps_v4_get_dwdm_site_detail",
            data: {
                site_id: siteid
            },
            showErrorMessage: false,
            success: (json) => {
                resolve({ res:json.result });
            },
            error: (error) => {
                console.error(error, "error fetch fme marker");
                reject(error);
            }
        });
    });
}

